// Read-only metadata from existing public content. No descriptions are stored/generated by AI.
import type { Context } from 'hono'
import type { AppEnv } from '../env'
import { getContent, type Settings } from './settings'
import type { PropertyRow } from './types'
import { parseJson } from './util'

const clean = (value: string) => value.replace(/\s+/g, ' ').trim()
const metadataPages = new Set(['/', '/search', '/offers', '/about', '/contact', '/enquiry', '/help', '/policies/privacy', '/policies/cancellation', '/policies/terms'])

export function publicCanonical(site: string, path: string): string | undefined {
  return metadataPages.has(path) ? new URL(path, site).href : undefined
}

export function propertyMetaDescription(p: Pick<PropertyRow, 'name' | 'destination' | 'highlights' | 'seo_description'>): string {
  if (p.seo_description?.trim()) return clean(p.seo_description)
  const highlights = parseJson<unknown>(p.highlights, [])
  const points = Array.isArray(highlights) ? highlights.filter((s): s is string => typeof s === 'string' && !!s.trim()).map(clean) : []
  const text = clean(`${p.name}${p.destination ? ` in ${p.destination}` : ''}. ${points.length ? points.join('. ') : 'View room categories and enquire for a personalised offer.'}`)
  if (text.length <= 160) return text
  const excerpt = text.slice(0, 157)
  const boundary = excerpt.lastIndexOf(' ')
  return excerpt.slice(0, boundary > 100 ? boundary : excerpt.length).replace(/[.,;:/\s]+$/, '') + '…'
}

export function travelAgencySchema(site: string, business: Settings['business']) {
  return {
    '@context': 'https://schema.org', '@type': 'TravelAgency', '@id': new URL('/#business', site).href,
    name: business.name, url: new URL('/', site).href, logo: new URL('/brand/logo-wide.webp', site).href,
    ...(business.email?.trim() ? { email: business.email.trim() } : {}),
    // Omit the development placeholder rather than asserting a fictitious phone.
    ...(business.phone?.trim() && business.phone.replace(/\D/g, '') !== '919000000000' ? { telephone: business.phone.trim() } : {}),
    ...(business.address?.trim() ? { address: business.address.trim() } : {}),
  }
}

const escapeXml = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;')

export function robotsText(site: string): string {
  return `User-agent: *\nDisallow: /staff\nDisallow: /admin\nDisallow: /my\nDisallow: /q/\nDisallow: /invoice/\nDisallow: /booking/\nDisallow: /enquiry/thanks/\nSitemap: ${new URL('/sitemap.xml', site).href}\n`
}

export async function publicSitemap(c: Context<AppEnv>) {
  const [props, content] = await Promise.all([
    c.env.DB.prepare("SELECT slug FROM properties WHERE status = 'live' ORDER BY slug").all<{ slug: string }>(),
    getContent(c.env),
  ])
  const paths = ['/', '/search', '/offers', '/about', '/contact', '/enquiry']
  // Do not promote the default, unapproved policy placeholder into the sitemap.
  for (const kind of ['privacy', 'cancellation', 'terms'] as const) {
    const policy = content.policies[kind]?.trim()
    if (policy && !policy.startsWith('This policy is being updated.')) paths.push(`/policies/${kind}`)
  }
  paths.push(...props.results.filter(p => !!p.slug).map(p => `/stay/${encodeURIComponent(p.slug)}`))
  const urls = [...new Set(paths.map(path => new URL(path, c.env.SITE_URL).href))]
  return c.body(`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${urls.map(url => `<url><loc>${escapeXml(url)}</loc></url>`).join('')}</urlset>`, 200, { 'content-type': 'application/xml; charset=utf-8' })
}
